// generar_310_proximos_clickeables.js
// CHIQUI Entre Señales — "Próximos" del dashboard: tarjetas clickeables
//
// En el dashboard, las tarjetas de "Próximos" mostraban info pero no se
// podía tocar para registrar. Ahora las que corresponden llevan a la
// acción con un toque:
//
//   · "Revisión corporal" (cada 30 días en Senior) → abre la revisión
//     corporal para registrarla. (Ya tenía la ruta definida; faltaba
//     que la tarjeta la usara.)
//   · "Chequeo preventivo" (cada 6 meses) → lleva a Salud, donde se
//     registra la visita veterinaria.
//
// Las tarjetas con acción muestran un "Registrar →" y responden al
// toque. Las que son solo informativas (vacunas, celo, etc.) siguen
// como antes.
//
// Cambios:
//   · components/DashboardContenido.tsx: el tipo de proximosItems ahora
//     admite 'url'; el render usa un enlace (Link) cuando hay url, y un
//     div normal cuando no.
//   · app/dashboard/page.tsx: se agrega url '/prevencion' al chequeo
//     preventivo (la revisión corporal ya tenía su url).
//
// No hay SQL.
//
// Uso:
//   node generar_310_proximos_clickeables.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "components/DashboardContenido.tsx",
    base64: ""
  },
  {
    ruta: "app/dashboard/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
